type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();

    assert!(len == r || len == c, "Length of input array must match one dimension of shape");

    if len == r {
        // Broadcast column vector: each row i is a[i] repeated c times
        let mut matrix = Vec::with_capacity(r);
        for i in 0..r {
            let row_val = a[i];
            let row = vec![row_val; c];
            matrix.push(row);
        }
        matrix
    } else {
        // Broadcast row vector: each row is the entire array a (length == c)
        let mut matrix = Vec::with_capacity(r);
        for _ in 0..r {
            matrix.push(a.clone());
        }
        matrix
    }
}